function boxHeader(v,pos,end){if(pos+8>end)throw Error('잘린 MP4 box');let size=v.getUint32(pos),head=8;const type=String.fromCharCode(...new Uint8Array(v.buffer,v.byteOffset+pos+4,4));if(size===1){if(pos+16>end)throw Error('잘린 MP4 확장 box');size=v.getUint32(pos+8)*4294967296+v.getUint32(pos+12);head=16}else if(size===0)size=end-pos;if(!Number.isSafeInteger(size)||size<head||pos+size>end)throw Error('잘못된 MP4 box 크기');return {type,size,head}}
