async function inspectMp4(blob){let p=0,ftyp=false,mdat=false,tracks=new Set();while(p<blob.size){const header=await blob.slice(p,p+16).arrayBuffer(),v=new DataView(header);if(v.byteLength<8)throw Error('잘린 MP4 파일');let size=v.getUint32(0),head=8;if(size===1){if(v.byteLength<16)throw Error('잘린 MP4 파일');size=v.getUint32(8)*4294967296+v.getUint32(12);head=16}else if(size===0)size=blob.size-p;const type=String.fromCharCode(...new Uint8Array(header,4,4));if(!Number.isSafeInteger(size)||size<head||p+size>blob.size)throw Error('정상 MP4 파일이 아닙니다');if(type==='ftyp'&&size>=16)ftyp=true;if(type==='mdat'&&size>head)mdat=true;if(type==='moov'){if(size>8*1024*1024)throw Error('MP4 메타데이터가 너무 큽니다');tracks=moovTracks(await blob.slice(p+head,p+size).arrayBuffer())}p+=size}if(!ftyp||!mdat||!tracks.size)throw Error('MP4 미디어 구조를 확인할 수 없습니다');return {video:tracks.has('vide'),audio:tracks.has('soun')}}
async function imageType(blob){const b=new Uint8Array(await blob.slice(0,32).arrayBuffer());if(b[0]===255&&b[1]===216&&b[2]===255)return 'jpg';if(b[0]===137&&String.fromCharCode(...b.slice(1,4))==='PNG')return 'png';if(String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP')return 'webp';if(String.fromCharCode(...b.slice(4,8))==='ftyp'&&/avif|avis/.test(String.fromCharCode(...b.slice(8))))return 'avif';throw Error('지원되는 원본 이미지 형식이 아닙니다')}
