async function collectComments(){const m=capturedModel(),code=m.code,key=code+':comments';if(researchBusy.has(key))return;researchBusy.add(key);const rec=researchStore[code]||(researchStore[code]={}),old=rec.comments;let rows=[],next='',hasMore=false,error='';const seen=new Set();try{const id=String(m.item.pk||m.item.id||'').split('_')[0];if(!/^\d+$/.test(id))throw Error('댓글 조회용 media ID가 없습니다');activitySet('comments','running','댓글 수집 중');const cursors=new Set();for(let page=0;page<10;page++){const j=await sameOriginJson(`/api/v1/media/${id}/comments/?can_support_threading=true&permalink_enabled=false&count=50${next?'&min_id='+encodeURIComponent(next):''}`);if(!Array.isArray(j.comments))throw Error('댓글 응답을 확인할 수 없습니다');for(const c of j.comments){const r=normalizedComment(c),id=r?.id||r?.username+':'+r?.text;if(r&&!seen.has(id)){seen.add(id);rows.push(r)}}hasMore=!!(j.has_more_comments||j.has_more_headload_comments);next=String(j.next_min_id||'');if(rows.length>=500){rows=rows.slice(0,500);hasMore=true;break}if(!hasMore)break;if(!next||cursors.has(next)){error='다음 페이지 정보를 확인할 수 없습니다';break}cursors.add(next)}live()}catch(e){if(e.name==='AbortError')throw e;error=e.message}finally{researchBusy.delete(key)}if(destroyed)return;if(!rows.length&&error&&old)rec.comments={...old,error};else rec.comments={rows,hasMore,error,fetchedAt:Date.now(),replyCoverage:'API 미리보기 답글'};saveResearch();activitySet('comments',error?'error':'success',`댓글 ${rows.length}개 수집`,error||(hasMore?'수집 한도 또는 미수집 페이지가 있습니다':'제공된 댓글 페이지 수집 완료'));renderSheet()}
function analyzeResearch(rec){const caption=String(rec.caption||''),speech=String(rec.stt?.text||''),ocr=String(rec.ocr?.text||''),text=[caption,speech,ocr].filter(Boolean).join('\n');const sentences=text.split(/\n+|(?<=[.!?。！？])\s+/).map(x=>x.trim()).filter(Boolean);return {firstCaption:caption.split(/\n|(?<=[.!?。！？])\s/)[0]||'',speechStart:rec.stt?.chunks?.filter(x=>x.start!=null&&x.start<3).map(x=>x.text).join(' ')||'',cta:[...new Set(sentences.filter(x=>/구매|주문|신청|예약|댓글|저장|공유|팔로우|링크|클릭|프로필|subscribe|follow|click|shop/i.test(x)))].slice(0,30),numbers:[...new Set(text.match(/\d[\d,.]*(?:\s*(?:%|퍼센트|원|만원|억|개|명|분|초|시간|일|개월|년))?/g)||[])].slice(0,60),prices:[...new Set(text.match(/(?:[₩$€]\s*[\d,.]+|\d[\d,.]*\s*(?:만\s?원|천\s?원|원|달러))/g)||[])].slice(0,40)}}
