function parseTime(s){const parts=String(s).replace(',','.').split(':').map(Number);if(parts.some(x=>!Number.isFinite(x)))return null;return parts.reduce((n,x)=>n*60+x,0)}
function normalizeResearchResult(kind,result){if(!result||typeof result!=='object'||typeof result.text!=='string'||result.text.length>100000)throw Error('인식 결과 형식 또는 크기 오류');const text=result.text;const out={text,source:String(result.source||'import').slice(0,60),at:Date.now()};if(kind==='stt'){out.chunks=(result.chunks||[]).slice(0,2000).map(x=>{const stamp=x.timestamp||[x.start,x.end],num=v=>v==null?null:Number.isFinite(Number(v))&&Number(v)>=0?Number(v):null;return {start:num(stamp[0]),end:num(stamp[1]),text:String(x.text||'').slice(0,10000)}});out.language=String(result.language||'').slice(0,30)}else{out.frames=(result.frames||[]).slice(0,60).map(x=>({time:x.time==null?null:Math.max(0,Number(x.time)||0),text:String(x.text||'').slice(0,10000),width:Number(x.width)||0,height:Number(x.height)||0,lines:(x.lines||[]).slice(0,300).map(l=>({text:String(l.text||'').slice(0,2000),confidence:Number(l.confidence)||0,bbox:l.bbox&&['x0','y0','x1','y1'].every(k=>Number.isFinite(l.bbox[k]))?l.bbox:null}))}));out.coverage=String(result.coverage||'가져온 결과').slice(0,200)}return out}
function parseResearchFile(kind,text,name){if(text.length>1000000)throw Error('1MB 이하 결과 파일을 선택해주세요');if(/\.json$/i.test(name)){const j=JSON.parse(text);return normalizeResearchResult(kind,Array.isArray(j)?{text:j.map(x=>x.text||'').join('\n'),[kind==='stt'?'chunks':'frames']:j}:j)}if(kind==='stt'){const chunks=[];const re=/(\d{1,2}:\d{2}(?::\d{2})?[.,]\d+)\s*-->\s*(\d{1,2}:\d{2}(?::\d{2})?[.,]\d+)[^\n]*\n([\s\S]*?)(?=\n\s*\n|$)/g;let m;while((m=re.exec(text)))chunks.push({start:parseTime(m[1]),end:parseTime(m[2]),text:m[3].replace(/<[^>]*>/g,'').trim()});return normalizeResearchResult(kind,{text:chunks.length?chunks.map(x=>x.text).join('\n'):text.trim(),chunks})}return normalizeResearchResult(kind,{text:text.trim(),frames:[]})}
function importResearch(kind){const m=capturedModel(),input=document.createElement('input');input.type='file';input.hidden=true;input.accept='.txt,.srt,.vtt,.json';input.setAttribute('data-ri-owned','');input.onchange=async()=>{try{const f=input.files?.[0];if(!f)return;const result=parseResearchFile(kind,await f.text(),f.name);live();(researchStore[m.code]||(researchStore[m.code]={}))[kind]=result;saveResearch();renderSheet()}catch(e){if(e.name!=='AbortError')notify(e.message)}finally{input.remove()}};input.oncancel=()=>input.remove();document.documentElement.appendChild(input);input.click()}
async function runResearch(kind){const m=capturedModel(),key=m.code+':'+kind;if(researchBusy.has(key))return;const token=[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,'0')).join(''),origin=new URL(BRIDGE_URL).origin;const w=window.open(BRIDGE_URL+'?mode=research&origin='+encodeURIComponent(location.origin)+'#'+token,'_blank','width=440,height=360');if(!w)throw Error('분석 창을 허용해주세요');researchBusy.add(key);activitySet(kind,'running',kind==='stt'?'음성 인식 중':'글자 인식 중');let dispose=()=>{},ready=false,payload=null,sent=false;const send=()=>{if(ready&&payload&&!sent){sent=true;w.postMessage({type:'RI_RESEARCH_INPUT',token,kind,...payload},origin)}};try{const resultPromise=new Promise((ok,no)=>{const timer=setTimeout(()=>no(Error('분석 시간초과: 결과 파일 가져오기를 사용할 수 있습니다')),10*60000),poll=setInterval(()=>{if(w.closed)no(abortError('분석 창 닫힘'))},500);const cancel=()=>no(abortError());const on=e=>{const d=e.data;if(e.origin!==origin||e.source!==w||!d||d.token!==token)return;if(d.type==='RI_RESEARCH_READY'){ready=true;send()}else if(d.type==='RI_RESEARCH_RESULT'&&d.kind===kind)try{ok(normalizeResearchResult(kind,d.result))}catch(error){no(error)}else if(d.type==='RI_RESEARCH_ERROR')no(Error(String(d.error||'인식 실패').slice(0,300)))};dispose=()=>{clearTimeout(timer);clearInterval(poll);removeEventListener('message',on);jobs.delete(cancel);try{w.close()}catch{}};jobs.add(cancel);addEventListener('message',on)});resultPromise.catch(()=>{});let item=m.item;if(m.type==='carousel')item=m.children[0];const url=kind==='stt'?(dashAudio(dash(item))||videoUrl(item)):(isVideo(item)?videoUrl(item):imageUrl(item));if(!url)throw Error(kind==='stt'?'음성이 있는 미디어를 선택해주세요':'인식할 원본 이미지 또는 영상이 없습니다');const media=await fetchMedia(url);payload={blob:media.blob,mediaType:isVideo(item)?'video':'photo'};send();const result=await resultPromise;live();(researchStore[m.code]||(researchStore[m.code]={}))[kind]=result;saveResearch();activitySet(kind,'success','인식 완료',result.text?'결과를 확인해주세요':'인식된 텍스트가 없습니다');renderSheet()}catch(e){if(e.name==='AbortError')activityClear();else activitySet(kind,'error','인식 실패',e.message);throw e}finally{dispose();researchBusy.delete(key)}}
async function exportData(format){const name=`RI_${new Date().toISOString().slice(0,10)}.${format}`,chosen=destination(name);let text,type;if(format==='json'){text=JSON.stringify({version:V,exportedAt:new Date().toISOString(),metrics:metricStore,research:researchStore},null,2);type='application/json'}else{const cols=['shortcode','username','postedAt','views','likes','comments','reposts','er','growth','multiple'];const cell=x=>{let s=String(x??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};text='\uFEFF'+[cols,...Object.values(metricStore).map(r=>{const d=deriveMetric(r);return cols.map(k=>r[k]??d[k]??'')})].map(row=>row.map(cell).join(',')).join('\r\n');type='text/csv;charset=utf-8'}await saveBlob(new Blob([text],{type}),name,await chosen)}
