async function saveBlob(blob,name,dest){live();dest=dest||await destination(name);live();if(dest.kind==='folder'||dest.kind==='file'){const f=dest.kind==='folder'?await dest.handle.getFileHandle(name,{create:true}):dest.handle;if(dest.kind==='file'){const wanted=name.match(/\.([^.]+)$/)?.[1],actual=f.name?.match(/\.([^.]+)$/)?.[1]?.toLowerCase();if(wanted&&actual&&actual!==wanted&&!(wanted==='jpg'&&actual==='jpeg'))throw Error(`원본 형식은 ${wanted.toUpperCase()}입니다. 파일 확장자를 맞춰 다시 선택해주세요`)}live();const w=await f.createWritable();try{live();await w.write(blob);live();await w.close()}catch(e){try{await w.abort()}catch{}throw e}return dest.label}const u=URL.createObjectURL(blob),a=document.createElement('a');a.setAttribute('data-ri-owned','');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),12000);return dest.label}
async function firstFrame(url){const x=await fetchMedia(url),u=URL.createObjectURL(x.blob),v=document.createElement('video');v.setAttribute('data-ri-owned','');v.muted=true;v.playsInline=true;v.preload='auto';v.style='position:fixed;left:-9999px;top:-9999px;width:2px;height:2px';document.body.appendChild(v);function wait(event,start,ms){return new Promise((ok,no)=>{const done=e=>{clearTimeout(to);v.removeEventListener(event,good);v.removeEventListener('error',bad);e?no(e):ok()},good=()=>done(),bad=()=>done(Error('영상 프레임 로드 실패')),to=setTimeout(()=>done(Error('프레임 로드 시간초과')),ms);v.addEventListener(event,good,{once:true});v.addEventListener('error',bad,{once:true});start()})}try{await wait('loadeddata',()=>{v.src=u;v.load()},12000);live();v.pause();if(v.currentTime!==0)await wait('seeked',()=>v.currentTime=0,4000);live();if(!v.videoWidth||!v.videoHeight)throw Error('영상 크기 확인 실패');const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);return await new Promise((ok,no)=>c.toBlob(b=>b?ok(b):no(Error('JPG 생성 실패')),'image/jpeg',.95))}finally{v.removeAttribute('src');v.load();v.remove();URL.revokeObjectURL(u)}}
async function model(m){live();if(m)return m;const id=currentId();if(!id?.code)throw Error('현재 콘텐츠 없음');if(current?.code===id.code&&freshModel(id.code))return current;return resolveCurrent()}
function activitySet(kind,state,message,detail=''){if(destroyed)return;activity.kind=kind;activity.state=state;activity.message=message;activity.detail=detail;renderSheet()}
function activityClear(){activity.kind='';activity.state='idle';activity.message='';activity.detail='';renderSheet()}
async function saveVideo(m,dest){m=m||capturedModel();const chosen=dest?Promise.resolve(dest):destination(names(m).video);activitySet('video','running','영상 저장 중');try{const d=await chosen,x=await verifiedVideo(m),name=names(m).video,where=await saveBlob(x.blob,name,d);activitySet('video','success','영상 저장 완료',`${name} · 오디오 포함 · ${where}`);return name}catch(e){if(e.name==='AbortError')activityClear();else activitySet('video','error','영상 저장 실패',err(e));throw e}}
async function saveAudio(m,dest){m=m||capturedModel();const name=names(m).audio,chosen=dest?Promise.resolve(dest):destination(name);activitySet('audio','running','음원 저장 중');try{const d=await chosen,url=dashAudio(dash(m.item));if(!url)throw Error('별도 음원 URL 없음');const x=await fetchMedia(url),tracks=await inspectMp4(x.blob);if(!tracks.audio||tracks.video)throw Error('분리 오디오 파일이 아닙니다');const where=await saveBlob(x.blob,name,d);activitySet('audio','success','음원 저장 완료',`${name} · ${where}`);return name}catch(e){if(e.name==='AbortError')activityClear();else activitySet('audio','error','음원 저장 실패',err(e));throw e}}
async function saveImage(m,dest){m=m||capturedModel();const cover=explicitCover(m.item),suggested=cover?`${base(m)}_c.${ext('',cover)}`:names(m).frame,chosen=dest?Promise.resolve(dest):destination(suggested);activitySet('image','running','이미지 저장 중');try{const d=await chosen;let blob,name;if(cover){const x=await fetchMedia(cover);blob=x.blob;name=`${base(m)}_c.${await imageType(blob)}`}else{blob=await firstFrame(videoUrl(m.item));name=names(m).frame}const where=await saveBlob(blob,name,d);activitySet('image','success','이미지 저장 완료',`${name} · ${cover?'실제 표지':'0.000초'} · ${where}`);return name}catch(e){if(e.name==='AbortError')activityClear();else activitySet('image','error','이미지 저장 실패',err(e));throw e}}
async function savePhoto(m,dest){m=m||capturedModel();const url=imageUrl(m.item),chosen=dest?Promise.resolve(dest):destination(`${base(m)}.${ext('',url)}`);activitySet('photo','running','사진 저장 중');try{const d=await chosen,x=await fetchMedia(url),name=`${base(m)}.${await imageType(x.blob)}`,where=await saveBlob(x.blob,name,d);activitySet('photo','success','사진 저장 완료',`${name} · ${where}`);return name}catch(e){if(e.name==='AbortError')activityClear();else activitySet('photo','error','사진 저장 실패',err(e));throw e}}
async function saveCarousel(m){m=m||capturedModel();const chosen=batchDestination(`${base(m)}_01.jpg`);activitySet('carousel','running','슬라이드 저장 중');try{const dest=await chosen,ch=m.children?.length?m.children:childItems(m.item);if(!ch.length)throw Error('슬라이드 항목 없음');let done=0;const errors=[];for(let i=0;i<ch.length;i++){live();try{const child=ch[i],vid=isVideo(child),x=vid?await verifiedVideo({code:mediaIdentity(child)||m.code,kind:m.kind,item:child}):await fetchMedia(imageUrl(child)),suffix=vid?'mp4':await imageType(x.blob),name=`${base(m)}_${String(i+1).padStart(2,'0')}.${suffix}`;await saveBlob(x.blob,name,dest);done++;activitySet('carousel','running',`슬라이드 저장 ${done}/${ch.length}`)}catch(e){if(e.name==='AbortError')throw e;errors.push(e)}}if(errors.length)throw batchFailure(done,ch.length,errors);activitySet('carousel','success',`슬라이드 ${done}개 완료`);return {done,failed:0}}catch(e){if(e.name==='AbortError')activityClear();else activitySet('carousel','error','슬라이드 저장 실패',err(e));throw e}}
async function saveVideoSet(m){m=m||capturedModel();const chosen=batchDestination(names(m).video),dest=await chosen,jobs=[()=>saveVideo(m,dest),()=>saveAudio(m,dest),()=>saveImage(m,dest)],out=[],errors=[];for(const fn of jobs){live();try{out.push(await fn())}catch(e){if(e.name==='AbortError')throw e;errors.push(e)}}if(errors.length){const e=batchFailure(out.length,3,errors);activitySet('all3','error',`3개 저장 ${out.length}/3`,e.message);throw e}activitySet('all3','success','3개 저장 3/3','완료');return out}
function metricValues(rec){if(rec?.schema!==2)rec=null;const d=deriveMetric(rec||{});return{views:fmtCount(rec?.views),likes:fmtCount(rec?.likes),comments:fmtCount(rec?.comments),reposts:fmtCount(rec?.reposts),er:fmtPct(d.er),growth:fmtPct(d.growth,true),multiple:fmtMul(d.multiple),date:shortDate(rec?.postedAt)}}
function gridRows(code){const rec=metricStore[code];if(!rec)return{row1:['','','',''],row2:['','','','']};const v=metricValues(rec);return{row1:[v.views?`▶${v.views}`:'',v.likes?`♥${v.likes}`:'',v.comments?`●${v.comments}`:'',v.reposts?`↻${v.reposts}`:''],row2:[v.er?`ER ${v.er}`:'',v.growth?`24h ${v.growth}`:'',v.multiple||'',v.date||'']}}
function gridAnchors(){return [...document.querySelectorAll('a[href*="/reel/"],a[href*="/reels/"],a[href*="/p/"],a[href*="/tv/"]')].map(a=>{const id=parseHref(a.getAttribute('href')||''),img=a.querySelector('img');if(!id||!img)return null;const w=a.offsetWidth||img.offsetWidth||0,h=a.offsetHeight||img.offsetHeight||0;if(w<70||h<70||w>innerWidth*.52||h>w*1.7)return null;return{a,id}}).filter(Boolean)}
function gridTargetId(){const xs=gridAnchors().map(x=>({...x,r:x.a.getBoundingClientRect()})).filter(x=>x.r.bottom>0&&x.r.top<innerHeight&&x.r.right>0&&x.r.left<innerWidth);if(!xs.length)return null;const cy=innerHeight/2;xs.sort((a,b)=>Math.abs((a.r.top+a.r.bottom)/2-cy)-Math.abs((b.r.top+b.r.bottom)/2-cy));return xs[0]?.id||null}
function renderCardMetrics(ui,code){if(destroyed)return;const rows=gridRows(code),box=ui?.querySelector('.ri98-metrics');if(!box)return;box.hidden=false;const els=box.querySelectorAll('.ri98-row');[rows.row1,rows.row2].forEach((vals,j)=>[...els[j].children].forEach((sp,i)=>{const text=vals[i]||'';if(sp.textContent!==text)sp.textContent=text;sp.classList.toggle('empty',!text)}))}
function removeCardUi(a){a.querySelector(':scope > .ri98-card-ui')?.remove();a.classList.remove('ri98-host')}
function ensureCard(a,id){a.classList.add('ri98-host');let ui=a.querySelector(':scope > .ri98-card-ui');if(!ui){ui=document.createElement('div');ui.className='ri98-card-ui';ui.innerHTML=`<button class="ri98-save" type="button" aria-label="저장">${dlIcon}</button><div class="ri98-metrics"><div class="ri98-row r1"><span></span><span></span><span></span><span></span></div><div class="ri98-row r2"><span></span><span></span><span></span><span></span></div></div>`;a.appendChild(ui);ui.querySelector('.ri98-save').addEventListener('click',onGridSave)}ui.dataset.code=id.code;ui.dataset.kind=id.kind;renderCardMetrics(ui,id.code);const r=a.getBoundingClientRect();if(r.bottom>-innerHeight*.5&&r.top<innerHeight*1.5)queueResolve(id)}
function feedItems(){const out=[];for(const article of document.querySelectorAll('article')){const link=article.querySelector('a[href*="/reel/"],a[href*="/p/"],a[href*="/tv/"]'),id=parseHref(link?.getAttribute('href')||'');if(!id)continue;const media=[...article.querySelectorAll('video,img')].sort((a,b)=>(b.clientWidth*b.clientHeight)-(a.clientWidth*a.clientHeight))[0];if(!media||media.clientWidth<180)continue;out.push({article,id,media})}return out}
function feedTargetId(){const xs=feedItems().map(x=>({...x,r:x.article.getBoundingClientRect()})).filter(x=>x.r.bottom>0&&x.r.top<innerHeight);if(!xs.length)return null;const cy=innerHeight/2;xs.sort((a,b)=>Math.abs((a.r.top+a.r.bottom)/2-cy)-Math.abs((b.r.top+b.r.bottom)/2-cy));return xs[0]?.id||null}
function ensureFeed(){const valid=new Set();for(const {article,id,media} of feedItems()){valid.add(article);article.classList.add('ri98-feed-article');mergeNative(id.code,article);let bar=article.querySelector('.ri98-feed');if(!bar){bar=document.createElement('div');bar.className='ri98-feed';bar.innerHTML='<div class="ri98-feed-title">RI</div><div class="ri98-feed-grid"></div>';const host=media.parentElement||article;host.classList.add('ri98-feed-host');host.appendChild(bar)}bar.dataset.code=id.code;renderResearchGrid(bar.querySelector('.ri98-feed-grid'),metricStore[id.code],true);queueResolve(id)}document.querySelectorAll('article.ri98-feed-article').forEach(a=>{if(!valid.has(a))a.querySelector('.ri98-feed')?.remove()})}
function ensureCards(){frameId=0;ensureQueued=false;if(destroyed)return;const xs=gridAnchors(),valid=new Set(xs.map(x=>x.a));document.querySelectorAll('a.ri98-host').forEach(a=>{if(!valid.has(a))removeCardUi(a)});for(const {a,id} of xs)ensureCard(a,id);ensureFeed();syncSurface()}
function scheduleEnsure(){if(destroyed||ensureQueued)return;ensureQueued=true;frameId=requestAnimationFrame(ensureCards)}
function queueResolve(id){if(destroyed||!id?.code||freshModel(id.code)||pending.has(id.code)||inFlight.has(id.code))return;const rec=metricStore[id.code],failed=failures.get(id.code);if(failed&&Date.now()-failed.at<RETRY_MS)return;if(rec?.schema===2&&Date.now()-Number(rec.apiAt||0)<CACHE_MS)return;pending.add(id.code);queue.push(id);pump()}
function pump(){while(!destroyed&&workers<2&&queue.length){const id=queue.shift();workers++;resolve(id.code,id.kind).catch(()=>{}).finally(()=>{pending.delete(id.code);workers--;if(!destroyed){refreshVisibleMetrics();pump()}})}}
function onGridSave(e){e.preventDefault();e.stopImmediatePropagation();const b=e.currentTarget,a=b.closest('a'),id=parseHref(a?.getAttribute('href')||'');if(id)openGridMenu(id,b)}
function positionMenu(trigger){if(!menu)return;const r=trigger.getBoundingClientRect(),mr=menu.getBoundingClientRect(),bottomLimit=Math.max(120,innerHeight-78);let left=Math.max(6,Math.min(innerWidth-mr.width-6,r.left)),top=r.bottom+6;if(top+mr.height>bottomLimit)top=Math.max(8,r.top-mr.height-6);menu.style.left=`${left}px`;menu.style.top=`${top}px`}
function addMenuButton(label,fn,wide=false){const b=document.createElement('button');b.textContent=label;if(wide)b.className='wide';b.onclick=async e=>{e.preventDefault();e.stopPropagation();const trigger=menu?.__trigger,html=trigger?.innerHTML;closeMenu();try{if(trigger){trigger.innerHTML='<span class="ri98-spinner"></span>';trigger.disabled=true}await fn();live();if(trigger)trigger.textContent='✓'}catch(x){if(!destroyed&&trigger)trigger.textContent=x.name==='AbortError'?'': '!';if(!destroyed&&x.name!=='AbortError')notify(x.message||'저장에 실패했습니다.')}finally{if(trigger&&!destroyed)later(()=>{trigger.innerHTML=html||dlIcon;trigger.disabled=false},1100)}};menu.appendChild(b)}
function openGridMenu(id,trigger){closeMenu();menu=document.createElement('div');menu.id='ri98-menu';menu.__trigger=trigger;document.documentElement.appendChild(menu);const build=m=>{if(destroyed||!menu||menu.__trigger!==trigger||parseHref(trigger.closest?.('a')?.getAttribute('href')||'')?.code&&parseHref(trigger.closest('a').getAttribute('href')).code!==id.code)return;menu.innerHTML='';if(currentId()?.code===m.code)current=m;if(m.type==='carousel')addMenuButton('슬라이드 전체',()=>saveCarousel(m),true);else if(m.type==='photo')addMenuButton('원본 사진',()=>savePhoto(m),true);else{addMenuButton('영상',()=>saveVideo(m));addMenuButton('음원',()=>saveAudio(m));addMenuButton('이미지',()=>saveImage(m));addMenuButton('3개 모두',()=>saveVideoSet(m))}positionMenu(trigger)};const cached=freshModel(id.code);if(cached){build(cached);return}const wait=document.createElement('button');wait.className='wide';wait.disabled=true;wait.textContent='콘텐츠 확인 중';menu.appendChild(wait);positionMenu(trigger);resolve(id.code,id.kind).then(build).catch(()=>{if(menu&&menu.__trigger===trigger)wait.textContent='확인할 수 없음'})}
function closeMenu(){menu?.remove();menu=null}
function modeLabel(){return saveMode==='folder'?(dirHandle?.name?`지정 폴더 · ${dirHandle.name}`:'지정 폴더'):saveMode==='prompt'?'매번 선택':'기본 다운로드'}
function currentRecord(){const id=currentId()?.code;return id?metricStore[id]||null:null}
function researchCells(rec,placeholder='확인중'){const v=metricValues(rec||{});return metricDefs.map(([key,label])=>({key,label,value:v[key]||placeholder,known:!!v[key]}))}
function renderResearchGrid(el,rec,compact=false){if(destroyed||!el)return;setHtml(el,researchCells(rec,compact?'·':'확인중').map(x=>`<div class="${x.known?'known':'pending'}"><span>${x.label}</span><b>${esc(x.value)}</b></div>`).join(''))}
function researchGridHtml(rec,cls=''){return`<div class="ri98-research-grid ${cls}">${researchCells(rec).map(x=>`<div class="${x.known?'known':'pending'}"><span>${x.label}</span><b>${esc(x.value)}</b></div>`).join('')}</div>`}
function activityHtml(){if(activity.state==='idle')return'';return`<div class="ri98-activity ${activity.state==='error'?'error':''}"><span class="dot"></span><div><b>${esc(activity.message)}</b>${activity.detail?`<small>${esc(activity.detail)}</small>`:''}</div></div>`}
function typeLabel(){return current?.type==='video'?'Reel/영상':current?.type==='photo'?'사진':current?.type==='carousel'?'슬라이드':'콘텐츠'}
function headHtml(title,back=false){return`<div class="ri98-head">${back?'<button data-a="back" class="icon">‹</button>':''}<div class="ri98-title">${esc(title)}</div><button data-a="close" class="icon">×</button></div>`}
function contentCompactHtml(){const title=current?`${current.username!=='unknown'?'@'+current.username:'RI'} · ${typeLabel()}`:'RI Research';return`${headHtml(title)}<div class="ri98-compact-body">${researchGridHtml(currentRecord(),'compact')}<div class="ri98-command"><button class="primary" data-a="save">저장</button><span class="mode">${esc(modeLabel())}</span><button data-a="detail">상세</button><button data-a="global" class="icon">•••</button></div>${activityHtml()}</div>`}
function tabBar(){const tabs=[['summary','요약'],['content','콘텐츠'],['comments','댓글'],['analysis','분석'],['media','미디어']];return`<div class="ri98-tabs">${tabs.map(([k,l])=>`<button data-tab="${k}" class="${detailTab===k?'active':''}">${l}</button>`).join('')}</div>`}
function summaryTab(){const r=currentRecord();return`<section class="ri98-section"><h3>성과 지표</h3>${researchGridHtml(r,'summary')}</section><section class="ri98-section"><h3>콘텐츠 정보</h3><div class="ri98-info"><div><span>계정</span><b>${esc(current?.username&&current.username!=='unknown'?'@'+current.username:'확인 중')}</b></div><div><span>유형</span><b>${esc(typeLabel())}</b></div><div><span>Shortcode</span><b>${esc(current?.code||'확인 중')}</b></div><div><span>저장 방식</span><b>${esc(modeLabel())}</b></div></div></section>`}
function stateCard(title,status,desc,items=[]){return`<div class="ri98-research-card"><div class="top"><b>${title}</b><span>${status}</span></div>${desc?`<p>${desc}</p>`:''}${items.length?`<div class="ri98-tags">${items.map(x=>`<span>${x}</span>`).join('')}</div>`:''}</div>`}
function contentTab(){const r=researchRecord(),m=current,busy=k=>researchBusy.has((m?.code||'')+':'+k);return `${researchGridHtml(currentRecord(),'tabtop')}${textCard('본문',r.caption)}${textCard('해시태그 / 언급',[...(r.hashtags||[]),...(r.mentions||[])].join(' '))}<div class="ri98-research-card"><b>음성 · 이 기기에서 인식</b><p>첫 실행 모델 다운로드 · 최대 180초</p>${researchButton('stt','음성 인식',!m||busy('stt')||m.type==='photo')}${researchButton('import-stt','결과 가져오기',!m)}</div>${textCard('음성 결과',r.stt?.text)}${r.stt?.chunks?.length?textCard('시간대별 문장',r.stt.chunks.map(x=>`${timeLabel(x.start)} ~ ${timeLabel(x.end)}  ${x.text}`).join('\n')):''}<div class="ri98-research-card"><b>화면 글자 · 이 기기에서 인식</b><p>영상: 2초 간격 최대 60프레임${m?.type==='carousel'?' · 첫 슬라이드 대상':''}</p>${researchButton('ocr','글자 인식',!m||busy('ocr'))}${researchButton('import-ocr','결과 가져오기',!m)}</div>${textCard('OCR 결과',r.ocr?.text)}${r.ocr?.frames?.length?textCard(r.ocr.coverage||'인식 범위',r.ocr.frames.map(f=>`${timeLabel(f.time)}\n${f.lines.length?f.lines.map(l=>l.text+(l.bbox?` [${l.bbox.x0},${l.bbox.y0}–${l.bbox.x1},${l.bbox.y1}]`:'')).join('\n'):f.text}`).join('\n\n')):''}`}
function commentsTab(){const c=researchRecord().comments,rows=c?.rows||[],counts={};for(const row of rows)for(const label of row.labels||[])counts[label]=(counts[label]||0)+1;return `${researchGridHtml(currentRecord(),'tabtop')}<div class="ri98-research-card">${researchButton('collect-comments','댓글 수집',!current||researchBusy.has(current.code+':comments'))}<p>수집 ${rows.length}개 · 답글 ${rows.reduce((n,x)=>n+(x.replies?.length||0),0)}개${c?.hasMore?' · 추가 미수집 댓글 있음':''}</p><p>답글은 API 미리보기 범위입니다. 분류는 문구 규칙에 따른 결과입니다.</p>${c?.error?`<p>${esc(c.error)}</p>`:''}</div>${textCard('분류',Object.entries(counts).map(([k,v])=>`${k} ${v}`).join(' · '))}${rows.map(c=>textCard('@'+c.username+(c.labels?.length?' · '+c.labels.join(' / '):''),c.text+(c.replies?.length?'\n\n'+c.replies.map(x=>'↳ @'+x.username+' '+x.text).join('\n'):''))).join('')}`}
function analysisTab(){const a=analyzeResearch(researchRecord());return `${researchGridHtml(currentRecord(),'tabtop')}${textCard('분석 기준','수집된 본문·음성·OCR의 문구를 규칙으로 추출합니다. 영상 구성이나 감정을 확정 판정하지 않습니다.')}${textCard('캡션 첫 문장',a.firstCaption)}${textCard('첫 3초 음성',a.speechStart)}${textCard('행동 유도 문구',a.cta.join('\n'))}${textCard('숫자',a.numbers.join(' · '))}${textCard('가격',a.prices.join(' · '))}`}
function mediaTab(){const metrics=researchGridHtml(currentRecord(),'tabtop');if(!current)return metrics+'<div class="ri98-empty">현재 콘텐츠를 확인하고 있습니다.</div>';if(current.type==='video')return metrics+`<div class="ri98-media-card"><div><b>영상</b><span>원본 MP4</span></div><button data-a="video">저장</button></div><div class="ri98-media-card"><div><b>음원</b><span>분리 오디오</span></div><button data-a="audio">저장</button></div><div class="ri98-media-card"><div><b>이미지</b><span>실제 표지 / 0.000초 프레임</span></div><button data-a="image">저장</button></div>`;if(current.type==='photo')return metrics+`<div class="ri98-media-card"><div><b>원본 사진</b><span>최대 해상도</span></div><button data-a="photo">저장</button></div>`;return metrics+`<div class="ri98-media-card"><div><b>슬라이드 전체</b><span>${current.children?.length||''}개 원본 개별 저장</span></div><button data-a="carousel">저장</button></div>`}
function detailBody(){return detailTab==='summary'?summaryTab():detailTab==='content'?contentTab():detailTab==='comments'?commentsTab():detailTab==='analysis'?analysisTab():mediaTab()}
function detailHtml(){const title=current?`${current.username!=='unknown'?'@'+current.username:'RI'} · ${typeLabel()}`:'RI Research';return`${headHtml(title,true)}${tabBar()}<div class="ri98-detail-body">${detailBody()}${activityHtml()}</div>`}
function listRow(icon,title,sub,value,action,disabled=false){return`<button ${disabled?'disabled':''} data-a="${action||''}" class="ri98-list-row"><span class="ri98-row-icon">${icon}</span><span class="ri98-row-copy"><b>${title}</b><small>${sub||''}</small></span>${value?`<span class="ri98-row-value">${esc(value)}</span>`:''}${!disabled&&action?'<span class="ri98-chevron">›</span>':''}</button>`}
function globalHtml(){return`${headHtml('RI 관리',true)}<div class="ri98-list"><div class="ri98-list-label">관리</div>${listRow('⇩','저장','다운로드 위치와 저장 방식',modeLabel(),'storage')}${listRow('▤','데이터','수집된 성과 기록과 history',`${Object.keys(metricStore).length}개`,'data')}${listRow('◎','리서치','댓글 · STT · OCR · 분석','','research')}${listRow('↻','업데이트',`현재 v${V}`,'','update')}<div class="ri98-list-label">시스템</div>${listRow('⎘','진단 복사','현재 상태를 클립보드로','','copy')}${listRow('×','RI 종료','현재 페이지에서 RI 제거','','destroy')}</div>`}
function storageHtml(){return`${headHtml('저장 방식',true)}<div class="ri98-choice-list"><button data-a="default" class="${saveMode==='default'?'active':''}"><div><b>기본 다운로드</b><small>브라우저 기본 다운로드 위치</small></div><span>${saveMode==='default'?'✓':''}</span></button><button data-a="folder" class="${saveMode==='folder'?'active':''}"><div><b>지정 폴더</b><small>${esc(dirHandle?.name||'한 번 지정하면 다시 사용')}</small></div><span>${saveMode==='folder'?'✓':''}</span></button><button data-a="prompt" class="${saveMode==='prompt'?'active':''}" ${typeof showSaveFilePicker!=='function'?'disabled':''}><div><b>매번 선택</b><small>저장할 때 파일 위치 선택</small></div><span>${saveMode==='prompt'?'✓':''}</span></button></div>`}
function dataHtml(){const recs=Object.values(metricStore),snaps=recs.reduce((s,x)=>s+(x.history?.filter(snapshotValid).length||0),0),accounts=new Set(recs.map(x=>x.username).filter(Boolean)).size;return `${headHtml('데이터',true)}<div class="ri98-data-summary"><div><b>${recs.length}</b><span>콘텐츠</span></div><div><b>${snaps}</b><span>검증된 기록</span></div><div><b>${accounts}</b><span>계정</span></div></div><div class="ri98-note">${researchButton('export-json','JSON 내보내기')}${researchButton('export-csv','CSV 내보내기')}<p>${storageWarning?'저장공간 기록 실패: 내보내기로 보관해주세요.':'북마클릿 전용 저장공간입니다.'}</p></div>`}
function researchHtml(){return `${headHtml('리서치',true)}<div class="ri98-list">${listRow('C','댓글','API 제공 범위 수집 · 미리보기 답글','','collect-comments',!current)}${listRow('S','음성 인식','이 기기에서 처리 · 모델 다운로드 · 최대 180초','','stt',!current||current.type==='photo')}${listRow('O','글자 인식','이 기기에서 처리 · 영상 2초 간격 최대 60프레임','','ocr',!current)}${listRow('S','음성 결과 가져오기','SRT / VTT / TXT / JSON','','import-stt',!current)}${listRow('O','OCR 결과 가져오기','TXT / JSON','','import-ocr',!current)}</div>`}
function renderSheet(){if(destroyed||!sheet||sheet.hidden)return;sheet.dataset.mode=sheetMode;sheet.dataset.view=sheetView;let html='';if(sheetView==='content'&&sheetMode==='compact')html=contentCompactHtml();else if(sheetView==='detail')html=detailHtml();else if(sheetView==='global')html=globalHtml();else if(sheetView==='storage')html=storageHtml();else if(sheetView==='data')html=dataHtml();else if(sheetView==='research')html=researchHtml();const top=sheet.querySelector('.ri98-detail-body')?.scrollTop||0;setHtml(sheet,html);const body=sheet.querySelector('.ri98-detail-body');if(body)body.scrollTop=top}
function openSheet(view='content',mode='compact'){sheetView=view;sheetMode=mode;sheet.hidden=false;if(launcher)launcher.hidden=true;closeMenu();renderSheet();scanQuiet()}
function closeSheet(){sheet.hidden=true;if(launcher){launcher.hidden=false;syncSurface()}}
function backSheet(){if(['storage','data','research'].includes(sheetView)){sheetView='global';sheetMode='panel'}else if(sheetView==='global'||sheetView==='detail'){sheetView='content';sheetMode='compact'}renderSheet()}
function openSaveMenu(trigger){const id=currentId();if(id?.code)openGridMenu(id,trigger)}
async function copyDiag(){const text=JSON.stringify({version:V,url:location.href,current:current?{code:current.code,type:current.type,username:current.username}:null,saveMode,activity,metricCount:Object.keys(metricStore).length},null,2);if(!navigator.clipboard?.writeText)throw Error('클립보드가 지원되지 않습니다');await navigator.clipboard.writeText(text);notify('진단을 복사했습니다.')}
async function sheetAct(a,target){try{if(a==='close')closeSheet();else if(a==='back')backSheet();else if(a==='detail'){sheetView='detail';sheetMode='expanded';detailTab='summary';renderSheet()}else if(a==='global'){sheetView='global';sheetMode='panel';renderSheet()}else if(a==='save')openSaveMenu(target);else if(['storage','data','research'].includes(a)){sheetView=a;renderSheet()}else if(a==='video')await saveVideo();else if(a==='audio')await saveAudio();else if(a==='image')await saveImage();else if(a==='photo')await savePhoto();else if(a==='carousel')await saveCarousel();else if(a==='default')setMode('default');else if(a==='folder')await chooseDir();else if(a==='prompt')setMode('prompt');else if(a==='update')await window.__RI_LOADER_REFRESH?.();else if(a==='copy')await copyDiag();else if(a==='destroy')destroy();else if(a==='collect-comments')await collectComments();else if(a==='stt'||a==='ocr')await runResearch(a);else if(a==='import-stt'||a==='import-ocr')importResearch(a.slice(7));else if(a==='export-json'||a==='export-csv')await exportData(a.slice(7))}catch(e){if(e.name!=='AbortError')notify(e.message||'작업을 완료하지 못했습니다.')}}
function notify(msg){if(destroyed||!msg)return;toast?.remove();const el=document.createElement('div');toast=el;el.id='ri98-toast';el.textContent=msg;document.documentElement.appendChild(el);later(()=>{el.remove();if(toast===el)toast=null},2500)}
function currentReelRoot(){const videos=[...document.querySelectorAll('video')].map(v=>({v,r:v.getBoundingClientRect()})).filter(x=>x.r.width>150&&x.r.height>200&&x.r.bottom>0&&x.r.top<innerHeight).sort((a,b)=>(b.r.width*b.r.height)-(a.r.width*a.r.height));let n=videos[0]?.v||null;for(let i=0;n&&i<6;i++,n=n.parentElement){if(n.querySelectorAll?.('button,[role="button"]').length>=3)return n}return videos[0]?.v?.parentElement||null}
function renderReelMetrics(){if(!reelMetrics)return;const id=routeId();if(!id||id.kind!=='reel'){reelMetrics.hidden=true;return}const root=currentReelRoot();mergeNative(id.code,root);const rec=metricStore[id.code];if(!rec){reelMetrics.hidden=false;renderResearchGrid(reelMetrics,null,true);queueResolve(id);return}reelMetrics.hidden=false;renderResearchGrid(reelMetrics,rec,true)}
function refreshVisibleMetrics(){if(destroyed)return;document.querySelectorAll('.ri98-card-ui').forEach(ui=>renderCardMetrics(ui,ui.dataset.code));document.querySelectorAll('.ri98-feed').forEach(bar=>renderResearchGrid(bar.querySelector('.ri98-feed-grid'),metricStore[bar.dataset.code],true));renderReelMetrics();if(!sheet?.hidden)renderSheet()}
function syncSurface(){if(destroyed||!launcher)return;const reel=/^\/reels?(?:\/|$)/i.test(location.pathname);launcher.classList.toggle('reel',reel);renderReelMetrics();const sig=location.pathname+location.search,id=currentId();if(sig!==routeTick||current&&current.code!==id?.code){routeTick=sig;scanEpoch++;current=null;closeMenu();if(id)queueResolve(id);if(!sheet?.hidden)scanQuiet()}else if(!sheet?.hidden&&id?.code&&!current&&!inFlight.has(id.code)&&Date.now()-(failures.get(id.code)?.at||0)>=RETRY_MS)scanQuiet()}
function scanQuiet(){if(destroyed)return;const id=currentId();if(!id?.code){scanEpoch++;current=null;renderSheet();return}if(current?.code!==id.code){current=null;renderSheet()}if(id.kind==='reel')mergeNative(id.code,currentReelRoot());resolveCurrent(false).catch(e=>{if(destroyed||e.name==='AbortError')return;if(currentId()?.code===id.code){current=null;renderSheet()}})}
